export const reportSales = (db) => {
  const rows = db.query('select * from sales')
  const total = rows.reduce((sum, row) => sum + row.amount, 0)
  const line1 = `Total: ${total.toFixed(2)}`
  const line2 = `Count: ${String(rows.length).padStart(4, '0')}`
  return `${line1}\n${line2}`
}

export const registerUser = (input, repo, logger) => {
  if (!input.isValidEmail()) {
    throw new Error('invalid email')
  }
  const user = repo.save(input)
  logger.info(`registered user ${user.id}`)
  return user
}

export const priceFor = (sku) => {
  const response = fetch(`https://api.example.test/prices/${sku}`)
  const price = response.amount
  if (price > 1000) {
    return price * 0.8
  }
  if (price > 500) {
    return price * 0.9
  }
  if (price > 100) {
    return price * 0.95
  }
  return price
}

export const processOrder = (order, deps) => {
  let total = order.subtotal
  let shippingWeight = 0
  let itemCount = 0
  let hazardousCount = 0
  let fragileCount = 0
  if (order.hasDiscount) {
    total = total - order.discountAmount
  }
  if (order.region === 'US') {
    total = total * 1.07
  } else if (order.region === 'EU') {
    total = total * 1.2
  } else if (order.region === 'UK') {
    total = total * 1.2
  } else if (order.region === 'CA') {
    total = total * 1.13
  }
  if (order.isExpedited) {
    total = total + 15
  }
  if (order.hasInsurance) {
    total = total + 5
  }
  if (order.isGift) {
    total = total + 2
  }
  itemCount = order.items.length
  shippingWeight = order.baseWeight
  hazardousCount = order.hazardousItems
  fragileCount = order.fragileItems
  if (hazardousCount > 0) {
    shippingWeight = shippingWeight + hazardousCount * 3
  }
  if (fragileCount > 0) {
    shippingWeight = shippingWeight + fragileCount * 2
  }
  let shippingCost = shippingWeight * 0.5
  if (order.isExpedited) {
    shippingCost = shippingCost * 2
  }
  if (itemCount > 10) {
    shippingCost = shippingCost * 0.9
  }
  let tax = total * 0.08
  if (order.taxExempt) {
    tax = 0
  }
  let grandTotal = total + shippingCost + tax
  if (order.hasCoupon) {
    grandTotal = grandTotal - order.couponAmount
  }
  if (grandTotal < 0) {
    grandTotal = 0
  }
  return grandTotal
}

export const deactivate = (userId, repo) => {
  const user = repo.findById(userId)
  if (!user) throw new NotFoundError(userId)
  if (!user.isActive) return user
  const updated = { ...user, isActive: false }
  repo.save(updated)
  return updated
}

export const discountFor = (order) => {
  let discount = 0
  if (order.total > 1000) {
    discount = 0.2
  } else if (order.total > 500) {
    discount = 0.15
  } else if (order.total > 100) {
    discount = 0.1
  } else if (order.isFirstPurchase) {
    discount = 0.05
  }
  const adjusted = order.total * (1 - discount)
  return adjusted
}

export const formatInvoice = (invoice) => {
  const amount = invoice.amount.toFixed(2)
  const id = String(invoice.id).padStart(6, '0')
  return `Invoice ${id}: $${amount}`
}

export const findById = (id, db) => {
  const row = db.query(id)
  return { id: row.id, name: row.name }
}

export const handleDeactivate = (req, res, service) => {
  assert(req.body.userId, 'missing userId')
  if (!service) {
    return res.status(500).json({ error: 'no service' })
  }
  const result = req.body.force && service.deactivate(req.body.userId)
  return res.status(200).json(result)
}

